import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';
import { LogoComponent } from '../../../shared/components/logo/logo.component';

@Component({
  selector: 'app-client-shell',
  standalone: true,
  imports: [CommonModule, RouterModule, LogoComponent],
  templateUrl: './client-shell.component.html',
  styleUrls: ['./client-shell.component.scss']
})
export class ClientShellComponent {
  constructor(public authService: AuthService, private router: Router) {}

  switchRole(role: string) {
    if (role === 'client') {
      this.router.navigate(['/client/home']);
    } else if (role === 'driver') {
      const u = this.authService.currentUser();
      if (u) {
        u.role = 'DRIVER';
        localStorage.setItem('mototaxi_user', JSON.stringify(u));
        this.authService.currentUser.set(u);
      }
      this.router.navigate(['/driver/dashboard']);
    } else if (role === 'admin') {
      const u = this.authService.currentUser();
      if (u) {
        u.role = 'ADMIN';
        localStorage.setItem('mototaxi_user', JSON.stringify(u));
        this.authService.currentUser.set(u);
      }
      this.router.navigate(['/admin/dashboard']);
    }
  }
}
<div class="min-h-screen bg-[#F4F5F7] flex justify-center py-0 md:py-6">
  <!-- Mobile Container matching interface.png mockup aspect ratio -->
  <div class="w-full max-w-[420px] bg-white md:rounded-[40px] shadow-2xl overflow-hidden flex flex-col h-[100vh] md:h-[880px] border border-gray-200 relative">

    <!-- Top App Bar -->
    <header class="px-5 pt-4 pb-2 bg-white flex items-center justify-between z-10">
      <button class="w-10 h-10 rounded-full flex items-center justify-center text-gray-700 hover:bg-gray-100">
        <i class="fa-solid fa-bars text-lg"></i>
      </button>

      <app-logo></app-logo>

      <button class="w-10 h-10 rounded-full flex items-center justify-center text-gray-700 hover:bg-gray-100">
        <i class="fa-solid fa-magnifying-glass text-lg"></i>
      </button>
    </header>

    <!-- Top Role Navigation Bar (exact match of interface.png) -->
    <div class="px-5 py-2 bg-white flex justify-start z-10">
      <div class="bg-gray-100 p-1 rounded-full inline-flex gap-1">
        <button class="bg-[#F5C518] text-[#1A1A1A] font-bold px-5 py-1.5 rounded-full text-xs shadow-sm">
          Client
        </button>
        <button (click)="switchRole('driver')" class="text-gray-500 font-medium px-4 py-1.5 rounded-full text-xs hover:text-gray-900 transition">
          Chauffeur
        </button>
        <button (click)="switchRole('admin')" class="text-gray-500 font-medium px-4 py-1.5 rounded-full text-xs hover:text-gray-900 transition">
          Admin
        </button>
      </div>
    </div>

    <!-- Main Content Area with router-outlet -->
    <main class="flex-1 overflow-y-auto relative flex flex-col">
      <router-outlet></router-outlet>
    </main>

    <!-- Bottom Navigation Bar -->
    <nav class="bg-white border-t border-gray-100 px-6 py-3 flex justify-between items-center z-20">
      <a routerLink="/client/home" routerLinkActive="text-[#F5C518]" [routerLinkActiveOptions]="{exact: true}" class="flex flex-col items-center gap-1 text-gray-400 hover:text-gray-700 text-xs font-semibold">
        <i class="fa-solid fa-compass text-lg"></i>
        <span>Trajet</span>
      </a>
      <a routerLink="/client/tracking" routerLinkActive="text-[#F5C518]" class="flex flex-col items-center gap-1 text-gray-400 hover:text-gray-700 text-xs font-semibold">
        <i class="fa-solid fa-location-dot text-lg"></i>
        <span>En direct</span>
      </a>
      <a routerLink="/client/history" routerLinkActive="text-[#F5C518]" class="flex flex-col items-center gap-1 text-gray-400 hover:text-gray-700 text-xs font-semibold">
        <i class="fa-regular fa-clock text-lg"></i>
        <span>Historique</span>
      </a>
      <a routerLink="/client/profile" routerLinkActive="text-[#F5C518]" class="flex flex-col items-center gap-1 text-gray-400 hover:text-gray-700 text-xs font-semibold">
        <i class="fa-regular fa-user text-lg"></i>
        <span>Profil</span>
      </a>
    </nav>

  </div>
</div>
